// src/components/ProjectPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import '../css/Projectpage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const { projectId } = useParams();

    const [renamingIndex, setRenamingIndex] = useState(null);
    const [menuOpenIndex, setMenuOpenIndex] = useState(null);
    const [projectName, setProjectName] = useState('');
    const [files, setFiles] = useState([]);
    const [activeIndex, setActiveIndex] = useState(0);
    const editorRef = useRef(null);
    const filePositionsRef = useRef({});
    const fileInputRef = useRef(null);

    // 프로젝트 이름 불러오기
    useEffect(() => {
        fetch(`http://localhost:4000/api/projects`, { credentials: 'include' })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    const proj = data.projects.find(p => String(p.id) === projectId);
                    if (proj) setProjectName(proj.project_name);
                }
            })
            .catch(console.error);
    }, [projectId]);

    // 커서 위치 복원
    useEffect(() => {
        if (!editorRef.current) return;
        if (files.length === 0) return;
        const pos = filePositionsRef.current[activeIndex] || { lineNumber: 1, column: 1 };
        editorRef.current.setPosition(pos);
        editorRef.current.revealPositionInCenter(pos);
    }, [activeIndex, files]);

    // 뒤로가기
    const handleBack = async () => {
        await Promise.all(
            files.map(file => {
                const blob = new Blob([file.content], { type: 'text/plain' });
                const formData = new FormData();
                formData.append('file', blob, file.name);
                return fetch(
                    `http://localhost:4000/api/projects/${projectId}/files/upload`,
                    {
                        method: 'POST',
                        credentials: 'include',
                        body: formData
                    }
                );
            })
        );
        navigate(-1);
    };


    // 프로젝트 이름 변경
    const handleRename = () => {
        const name = prompt('프로젝트 이름:', projectName);
        if (name) setProjectName(name);
    };

    // 새 파일 생성
    const handleNewFile = () => {
        setFiles(prev => {
            const newFiles = [...prev, { name: '', content: '' }];
            const newIndex = newFiles.length - 1;
            setActiveIndex(newIndex);
            setRenamingIndex(newIndex);   // 생성 직후 이름 편집 모드로 진입
            return newFiles;
        });
    };

    // 파일 업로드
    const handleUploadFile = e => {
        const file = e.target.files[0];
        if (!file) return;
        const formData = new FormData();
        formData.append('file', file);

        fetch(`http://localhost:4000/api/projects/${projectId}/files/upload`, {
            method: 'POST',
            credentials: 'include',
            body: formData
        })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setFiles(prev => [...prev, { name: data.file.file_name, content: '' }]);
                    setActiveIndex(files.length);
                } else {
                    alert('파일 업로드 실패');
                }
            })
            .catch(err => {
                console.error(err);
                alert('네트워크 오류');
            });
    };

    // 파일 삭제
    const handleDelete = idx => {
        if (window.confirm(`${files[idx].name || '파일'}을 삭제하시겠습니까?`)) {
            setFiles(prev => prev.filter((_, i) => i !== idx));
            setActiveIndex(idx > 0 ? idx - 1 : 0);
        }
    };

    // 파일 클릭
    const handleFileClick = idx => {
        if (editorRef.current && files.length) filePositionsRef.current[activeIndex] = editorRef.current.getPosition();
        setActiveIndex(idx);
        setMenuOpenIndex(null);
    };

    // 에디터 마운트
    const handleEditorMount = editor => {
        editorRef.current = editor;
        editor.onDidChangeCursorPosition(e => filePositionsRef.current[activeIndex] = e.position);
    };

    // 코드 실행
    const run = () => {
        if (!editorRef.current) return;
        try { eval(editorRef.current.getValue()); }
        catch (e) { console.error(e); }
    };

    return (
        <div className="replit-ide">
            <header className="replit-header">
                <div className="header-left">
                    <button className="icon-btn" onClick={handleBack}>🏠</button>
                    <span className="project-title" onClick={handleRename}>{projectName}</span>
                </div>
                <div className="header-right">
                    <input
                        type="file"
                        ref={fileInputRef}
                        style={{ display: 'none' }}
                        onChange={handleUploadFile}
                    />
                    <button className="run-btn" onClick={run}>▶ Run</button>

                </div>
            </header>
            <div className="replit-body">
                <aside className="file-explorer">
                    <div className="explorer-header">Files</div>
                    <div className="file-list">
                        {files.length === 0 ? (
                            <div className="empty-list"> 파일이 없습니다.</div>
                        ) : (
                            files.map((f, i) => (
                                <div key={i} className={`file-item ${activeIndex === i ? 'active' : ''}`}>
                                    {renamingIndex === i ? (
                                        <input
                                            autoFocus
                                            value={f.name}
                                            onChange={e => setFiles(prev => prev.map((file, idx) => idx === i ? { ...file, name: e.target.value } : file))}
                                            onBlur={e => {
                                                const val = e.target.value.trim();
                                                if (!val) {
                                                    // 이름이 없으면 해당 파일 삭제
                                                    setFiles(prev => prev.filter((_, idx) => idx !== i));
                                                    setActiveIndex(idx => (idx > 0 ? idx - 1 : 0));
                                                } else {
                                                    // 이름이 확정되면 파일을 서버에 저장
                                                    saveFileToServer({ name: val, content: f.content });
                                                }
                                                setRenamingIndex(null);
                                            }}
                                            onKeyDown={e => {
                                                if (e.key === 'Enter') e.target.blur(); // Enter치면 blur 처리
                                            }}
                                            placeholder="파일 이름"
                                        />
                                    ) : (
                                        <span className="file-label" onClick={() => handleFileClick(i)} onDoubleClick={() => setRenamingIndex(i)}>
                                            {f.name}
                                        </span>
                                    )}
                                    <div className="menu-container">
                                        <button className="menu-btn" onClick={() => setMenuOpenIndex(i === menuOpenIndex ? null : i)}>⋮</button>
                                        {menuOpenIndex === i && (
                                            <div className="menu-dropdown">
                                                <button onClick={() => { setRenamingIndex(i); setMenuOpenIndex(null); }}>이름 재설정</button>
                                                <button onClick={() => { handleDelete(i); setMenuOpenIndex(null); }}>삭제</button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                    <div className="explorer-footer">
                        <button className="new-file" onClick={handleNewFile}>+ File</button>
                    </div>
                </aside>
                <section className="main-pane">
                    {files.length > 0 && (
                        <>
                            <div className="editor-tabs">
                                <div className="tab active">{files[activeIndex]?.name}</div>
                            </div>
                            <Editor
                                height="calc(100% - 40px)"
                                theme="vs-dark"
                                language="c"
                                value={files[activeIndex].content}
                                onMount={handleEditorMount}
                                onChange={val => setFiles(prev => prev.map((file, idx) => idx === activeIndex ? { ...file, content: val } : file))}
                                options={{ fontSize: 14 }}
                            />
                        </>
                    )}
                    {files.length === 0 && (
                        <div className="empty-editor">새 파일을 추가하거나 업로드하세요.</div>
                    )}
                </section>
            </div>
        </div>
    );
}
